//! Math set at LaTeX's text sizes against pdfLaTeX (MacTeX 2026).
//!
//! `tests/size_oracle/expected.txt` holds the glyphs and rules pdfTeX placed
//! for each fixture formula, generated by `tools/size_oracle.py` (oracle
//! tooling; the reference pdflatex never runs here). Each fixture below
//! builds the math list TeX makes of the same source, lays it out with
//! [`CmMathMetrics::for_text_size`] (family 3 sized as amsmath declares it
//! when the fixture loads amsmath), and every glyph must have the same font,
//! character code and size as pdfTeX's and sit within 0.5 bp of it relative
//! to the formula's first glyph; rules likewise.

use flashtex_math_layout::cm::ExtensionSizing;
use flashtex_math_layout::{
    Atom, AtomClass, CmMathMetrics, Limits, MathFontMetrics, MathList, Nucleus, Style, layout,
    positioned_runs,
};

const BP: f64 = 72.0 / 72.27;
const TOLERANCE_BP: f64 = 0.5;

fn l(atoms: Vec<Atom>) -> MathList {
    MathList::new(atoms)
}
fn ord(c: char) -> Atom {
    Atom::ord(c)
}
fn bin(c: char) -> Atom {
    Atom::bin(c)
}
fn rel(c: char) -> Atom {
    Atom::rel(c)
}
fn punct(c: char) -> Atom {
    Atom::punct(c)
}
/// `\mathrm{c}`: a single upright character (TeX §1186).
fn rm(c: char) -> Atom {
    Atom::new(AtomClass::Ord, Nucleus::TextChar(c))
}
/// `\mskip<mu>mu`.
fn mu(m: f64) -> Atom {
    Atom::glue(m, 0.0)
}
/// `{\operator@font text}`: several upright characters.
fn op_font(text: &str) -> MathList {
    l(vec![Atom::new(AtomClass::Ord, Nucleus::Text(text.into()))])
}
fn sup(mut a: Atom, s: Vec<Atom>) -> Atom {
    a.superscript = Some(l(s));
    a
}
fn sub(mut a: Atom, s: Vec<Atom>) -> Atom {
    a.subscript = Some(l(s));
    a
}
/// `\mathop{\operator@font name}` with `\nolimits` or the default limits.
fn operator(name: &str, limits: Limits) -> Atom {
    Atom::new(AtomClass::Op, Nucleus::List(op_font(name))).with_limits(limits)
}
/// `\mathinner{p p p}`: `\ldotp` is cmmi "3A, `\cdotp` cmsy "01, both `\mathpunct`.
fn dots(c: char) -> Atom {
    Atom::new(AtomClass::Inner, Nucleus::List(l(vec![punct(c), punct(c), punct(c)])))
}
fn ldots() -> Atom {
    dots('.')
}
fn cdots() -> Atom {
    dots('\u{22C5}')
}
/// `'` and `''`: `^{\prime}` / `^{\prime\prime}`.
fn primes(a: Atom, n: usize) -> Atom {
    sup(a, vec![ord('\u{2032}'); n])
}
fn frac(num: Vec<Atom>, den: Vec<Atom>) -> Atom {
    Atom::frac(l(num), l(den))
}
const MINUS: char = '-';

fn build(name: &str) -> MathList {
    let atoms = match name {
        "k-inv-10" | "k-inv-11a-footnote" | "k-inv-12a" | "k-inv-11a-Large" => {
            vec![sup(rm('K'), vec![bin(MINUS), ord('1')])]
        }
        "m2-s-11a" => vec![
            sup(rm('m'), vec![ord('2')]),
            mu(3.0),
            sup(rm('s'), vec![bin(MINUS), ord('1')]),
        ],
        "d-x-10" => vec![rm('d'), ord('x')],
        "prime-f-10" => vec![primes(ord('f'), 1), Atom::open('('), ord('x'), Atom::close(')')],
        "prime-f2-11a" => vec![primes(ord('f'), 2), Atom::open('('), ord('x'), Atom::close(')')],
        "prime-footnote-10" => vec![primes(ord('x'), 1)],
        "prime-small-12a" => vec![primes(ord('g'), 1)],
        "epsilon-10" => vec![ord('\u{03F5}'), bin('+'), ord('\u{03B5}')],
        "epsilon-11a-footnote" => vec![ord('\u{03F5}'), ord('\u{03B5}')],
        // amsmath.sty 904-906: `\nonscript\mskip-\medmuskip\mkern5mu\mathbin
        // {\operator@font mod}\penalty900\mkern5mu\nonscript\mskip-\medmuskip`.
        "bmod-10a" | "bmod-11a-footnote" => vec![
            ord('a'),
            mu(-4.0),
            mu(5.0),
            Atom::new(AtomClass::Bin, Nucleus::List(op_font("mod"))),
            mu(5.0),
            mu(-4.0),
            ord('b'),
        ],
        // amsmath.sty 907-909: `\pod{{\operator@font mod}\mkern6mu#1}` =
        // `\allowbreak\mkern8mu(#1)` in text style.
        "pmod-11a" => vec![
            ord('a'),
            rel('\u{2261}'),
            ord('b'),
            mu(8.0),
            Atom::open('('),
            Atom::group(op_font("mod")),
            mu(6.0),
            ord('m'),
            Atom::close(')'),
        ],
        // latex.ltx 15560: `\allowbreak\mkern18mu({\operator@font mod}\,\,#1)`.
        "pmod-12" => vec![
            ord('a'),
            mu(18.0),
            Atom::open('('),
            Atom::group(op_font("mod")),
            mu(3.0),
            mu(3.0),
            ord('m'),
            Atom::close(')'),
        ],
        // amsmath `\dots` before `,` is `\dotsc`: `\@ldots` alone.
        "dotsc-10a" => vec![ord('a'), punct(','), ldots(), punct(','), ord('b')],
        // Before a binary operator it is `\dotsb@` = `\@cdots`.
        "dotsb-11a" => vec![ord('a'), bin('+'), cdots(), bin('+'), ord('b')],
        // amsmath `\cdots` before a letter: `\extrap@\@cdots` adds nothing.
        "cdots-11a-footnote" => vec![sub(ord('x'), vec![ord('1')]), cdots(), sub(ord('x'), vec![ord('n')])],
        // The kernel's `\ldots` is `\mathellipsis`.
        "ldots-10" => vec![
            Atom::open('('),
            ord('1'),
            punct(','),
            ldots(),
            punct(','),
            ord('n'),
            Atom::close(')'),
        ],
        // amsmath `\dots` before a right delimiter: `\dotso@`, `\@ldots\,`.
        "dots-paren-12a" => vec![
            Atom::open('('),
            sub(ord('x'), vec![ord('1')]),
            punct(','),
            ldots(),
            mu(3.0),
            Atom::close(')'),
        ],
        "sin2-10" | "sin2-11a-Large" => {
            vec![sup(operator("sin", Limits::NoLimits), vec![ord('2')]), ord('x')]
        }
        "lim-11a-footnote" => vec![
            sub(
                operator("lim", Limits::DisplayLimits),
                vec![ord('n'), rel('\u{2192}'), ord('\u{221E}')],
            ),
            sub(ord('a'), vec![ord('n')]),
        ],
        "frac-11a" => vec![frac(vec![ord('1')], vec![ord('2')])],
        "frac-11a-footnote" | "frac-10-footnote" => vec![frac(vec![ord('a')], vec![ord('b')])],
        "frac-12a-huge" => vec![frac(vec![ord('1')], vec![ord('x')])],
        "sum-11a" => vec![
            sup(
                sub(Atom::symbol('\u{2211}'), vec![ord('i'), rel('='), ord('1')]),
                vec![ord('n')],
            ),
            sub(ord('x'), vec![ord('i')]),
        ],
        "sum-10a-small" => vec![
            sub(Atom::symbol('\u{2211}'), vec![ord('i')]),
            sub(ord('x'), vec![ord('i')]),
        ],
        "sqrt-12a-footnote" => vec![Atom::new(
            AtomClass::Ord,
            Nucleus::Radical {
                radicand: l(vec![ord('x'), bin('+'), ord('1')]),
                degree: None,
            },
        )],
        "digits-11a-footnote" => vec![ord('1'), sup(ord('0'), vec![bin(MINUS), ord('3')])],
        "section-10" => vec![
            sup(ord('x'), vec![ord('2')]),
            bin('+'),
            sub(ord('\u{03B1}'), vec![ord('1')]),
        ],
        "subsection-11a" => vec![sub(sup(ord('x'), vec![ord('2')]), vec![ord('i')])],
        "LARGE-10" => vec![sup(ord('2'), vec![sup(ord('2'), vec![ord('n')])])],
        "small-10" => vec![sup(sub(ord('y'), vec![ord('i'), ord('j')]), vec![ord('2')])],
        "scriptsize-11a" => vec![sup(ord('e'), vec![ord('i'), ord('\u{03C0}')])],
        other => panic!("no builder for fixture {other}"),
    };
    l(atoms)
}

#[derive(Debug)]
struct RefGlyph {
    font: String,
    code: u16,
    size: f64,
    x: f64,
    y: f64,
}

#[derive(Debug)]
struct RefRule {
    x: f64,
    y: f64,
    w: f64,
    h: f64,
}

#[derive(Debug)]
struct Fixture {
    name: String,
    packages: String,
    text_pt: f64,
    source: String,
    glyphs: Vec<RefGlyph>,
    rules: Vec<RefRule>,
}

fn fixtures() -> Vec<Fixture> {
    let text = include_str!("size_oracle/expected.txt");
    let mut out: Vec<Fixture> = Vec::new();
    for line in text.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        let num = |i: usize| f[i].parse::<f64>().unwrap();
        match f.first().copied() {
            Some("fixture") => out.push(Fixture {
                name: f[1].into(),
                packages: f[3].into(),
                text_pt: num(4),
                source: String::new(),
                glyphs: Vec::new(),
                rules: Vec::new(),
            }),
            Some("#") => {
                if let Some(last) = out.last_mut() {
                    last.source = line[2..].into();
                }
            }
            Some("g") => out.last_mut().unwrap().glyphs.push(RefGlyph {
                font: f[1].into(),
                code: f[2].parse().unwrap(),
                size: num(3),
                x: num(4),
                y: num(5),
            }),
            Some("r") => out.last_mut().unwrap().rules.push(RefRule {
                x: num(1),
                y: num(2),
                w: num(3),
                h: num(4),
            }),
            _ => {}
        }
    }
    out
}

/// Compares one fixture; returns the largest deviation in bp or a reason.
fn compare(fx: &Fixture) -> Result<f64, String> {
    let mut m = CmMathMetrics::for_text_size(fx.text_pt);
    if fx.packages.split(',').any(|p| p == "amsmath") {
        m = m.with_extension(ExtensionSizing::Designs);
    }
    let root = layout(&build(&fx.name), Style::TEXT, &m);
    let runs = positioned_runs(&root, (0.0, 0.0));
    if runs.glyphs.len() != fx.glyphs.len() {
        return Err(format!(
            "{} glyphs, pdfTeX {}: ours {:?}",
            runs.glyphs.len(),
            fx.glyphs.len(),
            runs.glyphs.iter().map(|g| (m.font_name(g.font_id), g.gid)).collect::<Vec<_>>()
        ));
    }
    let first = &runs.glyphs[0];
    let first_font = m.font_name(first.font_id);
    let anchor = fx
        .glyphs
        .iter()
        .find(|r| r.font == first_font && r.code == first.gid)
        .ok_or_else(|| format!("pdfTeX has no {first_font} {}", first.gid))?;
    let mut used = vec![false; fx.glyphs.len()];
    let mut worst: f64 = 0.0;
    for g in &runs.glyphs {
        let font = m.font_name(g.font_id);
        let ox = (g.x - first.x) * BP;
        let oy = -(g.baseline_y - first.baseline_y) * BP;
        let best = fx
            .glyphs
            .iter()
            .enumerate()
            .filter(|(i, r)| !used[*i] && r.font == font && r.code == g.gid)
            .min_by(|(_, a), (_, b)| {
                let da = (a.x - anchor.x - ox).abs() + (a.y - anchor.y - oy).abs();
                let db = (b.x - anchor.x - ox).abs() + (b.y - anchor.y - oy).abs();
                da.total_cmp(&db)
            });
        let Some((i, r)) = best else {
            return Err(format!("{font} {} ({:?}) is not in pdfTeX's output", g.gid, g.ch));
        };
        used[i] = true;
        if (g.size * BP - r.size).abs() > 0.002 {
            return Err(format!("{font} {} at {:.4}bp, pdfTeX {:.4}bp", g.gid, g.size * BP, r.size));
        }
        let (dx, dy) = (ox - (r.x - anchor.x), oy - (r.y - anchor.y));
        worst = worst.max(dx.abs()).max(dy.abs());
        if dx.abs() > TOLERANCE_BP || dy.abs() > TOLERANCE_BP {
            return Err(format!("{font} {} ({:?}) off by ({dx:+.3}, {dy:+.3}) bp", g.gid, g.ch));
        }
    }
    if runs.rules.len() != fx.rules.len() {
        return Err(format!("{} rules, pdfTeX {}", runs.rules.len(), fx.rules.len()));
    }
    let mut ours: Vec<(f64, f64, f64, f64)> = runs
        .rules
        .iter()
        .map(|r| {
            (
                (r.x - first.x) * BP,
                -((r.y + r.h / 2.0) - first.baseline_y) * BP,
                r.w * BP,
                r.h * BP,
            )
        })
        .collect();
    let mut theirs: Vec<(f64, f64, f64, f64)> =
        fx.rules.iter().map(|r| (r.x - anchor.x, r.y - anchor.y, r.w, r.h)).collect();
    let key = |a: &(f64, f64, f64, f64), b: &(f64, f64, f64, f64)| b.1.total_cmp(&a.1).then(a.0.total_cmp(&b.0));
    ours.sort_by(key);
    theirs.sort_by(key);
    for (o, t) in ours.iter().zip(&theirs) {
        for (a, b) in [(o.0, t.0), (o.1, t.1), (o.2, t.2), (o.3, t.3)] {
            worst = worst.max((a - b).abs());
            if (a - b).abs() > TOLERANCE_BP {
                return Err(format!("rule {o:?} vs pdfTeX {t:?}"));
            }
        }
    }
    Ok(worst)
}

#[test]
fn math_at_text_sizes_matches_pdflatex() {
    let fixtures = fixtures();
    assert!(fixtures.len() >= 30, "{} fixtures", fixtures.len());
    let mut failures = Vec::new();
    for fx in &fixtures {
        match compare(fx) {
            Ok(worst) => println!("{:<24} {:>6}pt ok   max {worst:.3} bp   {}", fx.name, fx.text_pt, fx.source),
            Err(e) => {
                println!("{:<24} {:>6}pt FAIL {e}   {}", fx.name, fx.text_pt, fx.source);
                failures.push(format!("{}: {e}", fx.name));
            }
        }
    }
    assert!(failures.is_empty(), "{} of {} fixtures differ:\n{}", failures.len(), fixtures.len(), failures.join("\n"));
}

#[test]
fn text_size_tables_follow_fontmath() {
    let names = |m: &CmMathMetrics| {
        m.families.map(|row| row.map(|f| f.name).join("/")).join(" ")
    };
    let ten = CmMathMetrics::for_text_size(10.0);
    assert_eq!(names(&ten), names(&CmMathMetrics::latex_10pt()));
    assert_eq!(ten.sizes, CmMathMetrics::latex_10pt().sizes);
    let twelve = CmMathMetrics::for_text_size(12.0);
    assert_eq!(names(&twelve), names(&CmMathMetrics::latex_12pt()));
    // pdfTeX `\fontname\textfont0/\scriptfont0/...` in an article (see
    // `cm::declare_math_sizes` / `cm::design_for`).
    assert_eq!(names(&CmMathMetrics::for_text_size(9.0)), "cmr9/cmr6/cmr5 cmmi9/cmmi6/cmmi5 cmsy9/cmsy6/cmsy5");
    assert_eq!(names(&CmMathMetrics::for_text_size(10.95)), "cmr10/cmr8/cmr6 cmmi10/cmmi8/cmmi6 cmsy10/cmsy8/cmsy6");
    assert_eq!(names(&CmMathMetrics::for_text_size(14.4)), "cmr12/cmr10/cmr7 cmmi12/cmmi10/cmmi7 cmsy10/cmsy10/cmsy7");
    assert_eq!(names(&CmMathMetrics::for_text_size(17.28)), "cmr17/cmr12/cmr10 cmmi12/cmmi12/cmmi10 cmsy10/cmsy10/cmsy10");
    assert_eq!(CmMathMetrics::for_text_size(24.88).sizes, [24.88, 20.74, 17.28]);
    // An undeclared size: .7 and .5 as TeX multiplies them.
    let odd = CmMathMetrics::for_text_size(11.0).sizes;
    assert_eq!(odd[0], 11.0);
    assert!((odd[1] - 7.7).abs() < 1e-4 && (odd[2] - 5.5).abs() < 1e-9, "{odd:?}");
}
